const LON0 = -11;
const LAT1 = 61;
const K = 2565.4826647648797;
const merc = (lat: number) => Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));

const round = (v: number) => Math.round(v * 100) / 100;

/* Rounded so server and browser render identical coordinates (Math.log/tan can differ in the last digits) */
export function projectToMap(lat: number, lon: number) {
  return { x: round(((lon - LON0) * Math.PI / 180) * K), y: round((merc(LAT1) - merc(lat)) * K) };
}
